{
  "story": "Recursion builds up a stack of deferred multiplications until it hits the base case, then unwinds the results.",
  "aha": {
    "stateId": "base_case",
    "observation": "When factorial(0) returns 1, the stacked calls resolve in reverse order."
  },
  "layout": {
    "preset": "stepper",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.step",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.step",
        "regions": "variant.regions",
        "values": "variant.states.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "variant.states.why",
        "target": "variant.states.calloutRegion",
        "text": "variant.states.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "variant.states.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "label": "Step",
      "options": [
        "factorial(3)",
        "factorial(2)",
        "factorial(1)",
        "factorial(0)",
        "Return 1",
        "Return 2",
        "Return 6"
      ]
    },
    {
      "id": "res",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "regions": [
          {
            "id": "stack",
            "label": "Call Stack",
            "kind": "list",
            "values": [
              "fact(3)",
              "fact(2)",
              "fact(1)",
              "fact(0)"
            ]
          }
        ],
        "states": [
          {
            "id": "call_3",
            "label": "Step 1",
            "short": "fact(3)",
            "sentence": "factorial(3) calls factorial(2).",
            "why": "Waiting for multiplier.",
            "active": ["stack"],
            "calloutRegion": "stack",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "1"
              }
            ]
          },
          {
            "id": "call_2",
            "label": "Step 2",
            "short": "fact(2)",
            "sentence": "factorial(2) calls factorial(1).",
            "why": "Waiting for multiplier.",
            "active": ["stack"],
            "calloutRegion": "stack",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "2"
              }
            ]
          },
          {
            "id": "call_1",
            "label": "Step 3",
            "short": "fact(1)",
            "sentence": "factorial(1) calls factorial(0).",
            "why": "Waiting for multiplier.",
            "active": ["stack"],
            "calloutRegion": "stack",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "3"
              }
            ]
          },
          {
            "id": "base_case",
            "label": "Step 4",
            "short": "fact(0)",
            "sentence": "factorial(0) reaches the base case and returns 1.",
            "why": "Base case stops recursion.",
            "active": ["stack"],
            "calloutRegion": "stack",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "4"
              }
            ]
          },
          {
            "id": "ret_1",
            "label": "Step 5",
            "short": "Return 1",
            "sentence": "factorial(1) computes 1 * 1 and returns 1.",
            "why": "Unwinding stack.",
            "active": ["stack"],
            "calloutRegion": "stack",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "3"
              }
            ]
          },
          {
            "id": "ret_2",
            "label": "Step 6",
            "short": "Return 2",
            "sentence": "factorial(2) computes 2 * 1 and returns 2.",
            "why": "Unwinding stack.",
            "active": ["stack"],
            "calloutRegion": "stack",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "2"
              }
            ]
          },
          {
            "id": "ret_3",
            "label": "Step 7",
            "short": "Return 6",
            "sentence": "factorial(3) computes 3 * 2 and returns 6.",
            "why": "Final result ready.",
            "active": ["stack"],
            "calloutRegion": "stack",
            "readouts": [
              {
                "id": "depth",
                "label": "Stack Depth",
                "value": "1"
              }
            ]
          }
        ]
      }
    ]
  }
